/**
 * Image Generation Utilities
 *
 * Handles technical comments (sentinels) and model discovery for the
 * experimental image generation feature.
 */
import { z } from 'zod';

const SENTINEL_IMAGE_REQUEST_PREFIX = '<!-- naidan_experimental_image_request';
const SENTINEL_IMAGE_RESPONSE_PREFIX = '<!-- naidan_experimental_image_response';
export const SENTINEL_IMAGE_PENDING = '<!-- naidan_experimental_image_generation_pending -->';
export const SENTINEL_IMAGE_PROCESSED = '<!-- naidan_experimental_image_generation_processed -->';

export const IMAGE_BLOCK_LANG = 'naidan_experimental_image';

export const GeneratedImageBlockSchema = z.object({
  binaryObjectId: z.string(),
  displayWidth: z.number(),
  displayHeight: z.number(),
  width: z.number().optional(),
  height: z.number().optional(),
  prompt: z.string().optional(),
  steps: z.number().optional(),
  seed: z.number().optional(),
});

export type GeneratedImageBlock = z.infer<typeof GeneratedImageBlockSchema>;

export const ImageRequestParamsSchema = z.object({
  width: z.number().optional(),
  height: z.number().optional(),
  model: z.string().optional(),
  count: z.number().optional(),
  persistAs: z.enum(['original', 'webp', 'jpeg', 'png']).default('original'),
  steps: z.number().optional(),
  seed: z.union([z.number(), z.literal('browser_random')]).optional(),
});

export type ImageRequestParams = z.infer<typeof ImageRequestParamsSchema>;

export const ImageResponseParamsSchema = z.object({
  count: z.number().optional(),
});

export type ImageResponseParams = z.infer<typeof ImageResponseParamsSchema>;

/**
 * Finds all image generation models from a list of available models.
 * Currently looks for any model starting with 'x/z-image-turbo:'.
 */
export function getImageGenerationModels({ models }: { models: string[] }): string[] {
  return models.filter(m => m.startsWith('x/z-image-turbo:') || m.startsWith('x/flux2-klein:'));
}

/**
 * Creates a sentinel marker for an image generation request.
 */
export function createImageRequestMarker({ width, height, model, count, persistAs, steps, seed }: { width?: ImageRequestParams['width'], height?: ImageRequestParams['height'], model?: ImageRequestParams['model'], count?: ImageRequestParams['count'], persistAs: ImageRequestParams['persistAs'], steps?: ImageRequestParams['steps'], seed?: ImageRequestParams['seed'] }): string {
  const params = JSON.stringify({ width, height, model, count, persistAs, steps, seed });
  return `${SENTINEL_IMAGE_REQUEST_PREFIX} ${params} -->`;
}

/**
 * Creates a sentinel marker for an image generation response.
 */
export function createImageResponseMarker({ count }: { count?: ImageResponseParams['count'] }): string {
  const params = JSON.stringify({ count });
  return `${SENTINEL_IMAGE_RESPONSE_PREFIX} ${params} -->`;
}

/**
 * Checks if the content contains an image generation request.
 */
export function isImageRequest({ content }: { content: string }): boolean {
  return content.includes(SENTINEL_IMAGE_REQUEST_PREFIX);
}

/**
 * Checks if the content contains an image generation response metadata.
 */
export function isImageResponse({ content }: { content: string }): boolean {
  return content.includes(SENTINEL_IMAGE_RESPONSE_PREFIX);
}

/**
 * Parses the image request parameters from the content.
 */
export function parseImageRequest({ content }: { content: string }): ImageRequestParams | null {
  const match = content.match(/<!-- naidan_experimental_image_request (\{.*?\}) -->/);
  if (!match) return null;
  try {
    const result = ImageRequestParamsSchema.safeParse(JSON.parse(match[1] || '{}'));
    if (!result.success) {
      console.warn('Failed to validate image request params', result.error);
      return null;
    }
    const data = result.data;
    return {
      width: data.width ?? 512,
      height: data.height ?? 512,
      model: data.model ?? '',
      count: data.count ?? 1,
      persistAs: data.persistAs ?? 'original',
      steps: data.steps,
      seed: data.seed,
    };
  } catch (e) {
    console.warn('Failed to parse image request params JSON', e);
    return null;
  }
}

/**
 * Parses the image response parameters from the content.
 */
export function parseImageResponse({ content }: { content: string }): ImageResponseParams | null {
  const match = content.match(/<!-- naidan_experimental_image_response (\{.*?\}) -->/);
  if (!match) return null;
  try {
    const result = ImageResponseParamsSchema.safeParse(JSON.parse(match[1] || '{}'));
    if (!result.success) {
      console.warn('Failed to validate image response params', result.error);
      return null;
    }
    const data = result.data;
    return {
      count: data.count ?? 1,
    };
  } catch (e) {
    console.warn('Failed to parse image response params JSON', e);
    return null;
  }
}

/**
 * Removes all naidan-specific technical comments from the content.
 * Also removes a trailing newline if it immediately follows a sentinel.
 */
export function stripNaidanSentinels({ content }: { content: string }): string {
  return content.replace(/<!-- naidan_.*? -->\n?/g, '');
}

/**
 * Checks if the content indicates a pending image generation.
 */
export function isImageGenerationPending({ content }: { content: string }): boolean {
  return content.includes('<!-- naidan_experimental_image_generation_pending');
}

/**
 * Checks if the content indicates a processed image generation.
 */
export function isImageGenerationProcessed({ content }: { content: string }): boolean {
  return content.includes(SENTINEL_IMAGE_PROCESSED);
}

/**
 * Counts the number of generated image blocks in the content.
 */
export function countGeneratedImages({ content }: { content: string }): number {
  const codeBlockRegex = new RegExp('```' + IMAGE_BLOCK_LANG, 'g');
  return (content.match(codeBlockRegex) || []).length;
}

/**
 * Calculates display dimensions based on raw dimensions or fallback.
 * Follows the project convention of 80% scaling for UI display.
 */
export function getDisplayDimensions({ width, height, displayWidth, displayHeight }: {
  width?: number,
  height?: number,
  displayWidth?: number,
  displayHeight?: number,
}): { width: number, height: number } {
  if (width !== undefined && height !== undefined) {
    return {
      width: Math.round(width * 0.8),
      height: Math.round(height * 0.8),
    };
  }
  return {
    width: displayWidth ?? 512,
    height: displayHeight ?? 512,
  };
}

/**
 * Gets statistics about generated images in the content.
 */
export function getImageStats({ content }: { content: string }): {
  generatedCount: number,
  totalCount: number | undefined,
} {
  const response = parseImageResponse({ content });
  const generatedCount = countGeneratedImages({ content });
  return {
    generatedCount,
    totalCount: response?.count,
  };
}

/**
 * Calculates the progress of image generation from the content.
 * Returns total count, remaining count, and current step within the active generation.
 */
export function getImageGenerationProgress({ content }: { content: string }): {
  totalCount: number | undefined,
  remainingCount: number | undefined,
  currentStep: number | undefined,
  totalSteps: number | undefined,
} {
  const response = parseImageResponse({ content });

  // Extract progress info from the pending sentinel if present
  // Format: <!-- naidan_experimental_image_generation_pending {"currentStep":1,"totalSteps":10} -->
  const pendingMatch = content.match(/<!-- naidan_experimental_image_generation_pending (\{.*?\}) -->/);
  let currentStep: number | undefined;
  let totalSteps: number | undefined;

  if (pendingMatch) {
    try {
      const params = JSON.parse(pendingMatch[1]!);
      currentStep = params.currentStep;
      totalSteps = params.totalSteps;
    } catch (e) { /* ignore parse errors */ }
  }

  if (!response) return { totalCount: undefined, remainingCount: undefined, currentStep, totalSteps };

  const totalCount = response.count ?? 1;

  // Count already generated images in both OPFS (Markdown block) and local (img tag) modes
  const processedCount = countGeneratedImages({ content }) + (content.match(/<img/g) || []).length;

  return {
    totalCount,
    remainingCount: Math.max(0, totalCount - processedCount),
    currentStep,
    totalSteps,
  };
}

// Export internal state and logic used only for testing here. Do not reference these in production logic.
// ESLint-required for TypeScript modules.
export const TEST_ONLY = {
  SENTINEL_IMAGE_REQUEST_PREFIX,
  SENTINEL_IMAGE_RESPONSE_PREFIX,
};
